import { OrderDetail } from '@/components/admin/orders/order-detail'

/**
 * Admin → Orders → one order.
 *
 * The ref is a URL segment, so it is decoded before use: order references are
 * generated by the shop and are plain, but a hand-typed or shared link should not
 * be able to hand a half-decoded string to the API.
 */
export default async function AdminOrderDetailPage({
  params,
}: {
  params: Promise<{ orderRef: string }>
}) {
  const { orderRef } = await params
  return <OrderDetail orderRef={decodeURIComponent(orderRef)} />
}
